"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

from heapq import heappop, heappush

Cell = tuple[int, int]  # (row, col)


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = next(
        ((row, col) for row, tiles in enumerate(grid)
         for col, tile in enumerate(tiles) if tile == "S"),
        None,
    )
    if start is None:
        return None

    frontier: list[tuple[int, Cell]] = [(0, start)]
    costs: dict[Cell, int] = {start: 0}
    previous: dict[Cell, Cell] = {}
    while frontier:
        cost, cell = heappop(frontier)
        if cost != costs[cell]:
            continue
        row, col = cell
        if grid[row][col] == "G":
            path = [cell]
            while cell in previous:
                cell = previous[cell]
                path.append(cell)
            path.reverse()
            return path

        for next_row, next_col in ((row - 1, col), (row + 1, col),
                                   (row, col - 1), (row, col + 1)):
            if not (0 <= next_row < len(grid)):
                continue
            if not (0 <= next_col < len(grid[next_row])):
                continue
            tile = grid[next_row][next_col]
            if tile == "#":
                continue
            neighbour = (next_row, next_col)
            next_cost = cost + (3 if tile == "D" else 1)
            if neighbour in costs and next_cost >= costs[neighbour]:
                continue
            costs[neighbour] = next_cost
            previous[neighbour] = cell
            heappush(frontier, (next_cost, neighbour))
    return None


